  const math=mathPairs.split('\n').map(l=>l.split('|')).sort((a,b)=>b[0].length-a[0].length);
  function curriculum(copy){
    if(exact[copy])return exact[copy];
    let s=copy;
    let match=s.match(/^(\d+)까지(?:의 수)? 알기(?:와 쓰기)?$/);if(match)return 'Understanding numbers up to '+match[1]+(s.includes('쓰기')?' and writing them':'');
    match=s.match(/^(\d+)까지 쓰기$/);if(match)return 'Writing numbers up to '+match[1];
    match=s.match(/^(\d+)에 대한 다른 이름 알기$/);if(match)return 'Other names for '+match[1];
    match=s.match(/^빼지는 수가 (\d+)까지인 뺄셈(.*)$/);if(match)return 'Subtraction from numbers up to '+match[1]+match[2];
    match=s.match(/^합 (\d+)인 덧셈(.*)$/);if(match)return 'Addition with a sum of '+match[1]+match[2].replace(/알기/g,' · Understanding');
    // A compositional label is used for long curriculum titles outside the demo.
    const protectedTerms=[];
    for(const [ko,en] of math)s=s.split(ko).join(' §'+(protectedTerms.push(en)-1)+'§ ');
    s=s.replace(/(\d+)까지/g,'up to $1').replace(/(\d+)에서/g,'from $1').replace(/\b(\d+) 자리/g,'$1-digit');
    s=s.replace(/알기와 쓰기/g,'understanding and writing').replace(/알기/g,'understanding').replace(/쓰기/g,'writing').replace(/구하기/g,'finding').replace(/나타내기/g,'representing').replace(/계산하기/g,'calculating').replace(/읽기/g,'reading').replace(/그리기/g,'drawing');
    s=s.replace(/의/g,' of ').replace(/와|과/g,' and ').replace(/까지/g,' up to ').replace(/에서/g,' from ').replace(/수/g,' numbers ');
    s=s.replace(/에서|부터/g,' from ').replace(/으로|로/g,' using ').replace(/따른|따라/g,' by ').replace(/에게|에/g,' in ').replace(/를|을|이|가|하는|하기|하고/g,' ').replace(/쪽/g,' side ').replace(/몇/g,' how many ').replace(/씩/g,' each ').replace(/개/g,' items ').replace(/번/g,' times ');
    s=s.replace(/§(\d+)§/g,(_,i)=>protectedTerms[Number(i)]).replace(/\s+/g,' ').trim();
    return s;
  }
